module ActionController
module RateLimiting;extend ActiveSupport::Concern;module ClassMethods;def rate_limit(to:,within:,by:->{request.remote_ip},with:->{head:too_many_requests},store:cache_store,name:nil,**options)before_action->{rate_limiting(to:to,within:within,by:by,with:with,store:store,name:name)},**options;end;end;private;def rate_limiting(to:,within:,by:,with:,store:,name:)cache_key=["rate-limit",controller_path,name,instance_exec(&by)].compact.join(":");count=store.increment(cache_key,1,expires_in:within);if count&&count>to;ActiveSupport::Notifications.instrument("rate_limit.action_controller",request:request) do instance_exec(&with);end;end;end;end;end
